import{_ as e,c as o,o as c,Q as t}from"./chunks/framework.5f28ab71.js";const h=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"compiler/设计原则/1-模板编译的核心流程.md","lastUpdated":1724243587000}'),d={name:"compiler/设计原则/1-模板编译的核心流程.md"},r=t('<h2 id="模板编译的核心流程" tabindex="-1">模板编译的核心流程 <a class="header-anchor" href="#模板编译的核心流程" aria-label="Permalink to &quot;模板编译的核心流程&quot;">​</a></h2><p>我们知道，对于 <code>vue</code> 中的 <code>compiler</code> 而言，它的核心作用就是把 <code>template模板</code> 编译成 <code>render 函数</code> ，那么在这样的一个编译过程中，它的一个具体流程是什么呢？这一小节我们来看一下。</p><p>从上一小节的源码中，我们可以看到 <strong>编译器 <code>compiler</code></strong> 本身只是一段程序，它的作用就是：<strong>把 <code>A</code> 语言，编译成 <code>B</code> 语言。</strong></p><p>在这样的一个场景中 <code>A</code> 语言，我们把它叫做 <strong>源代码</strong>。而 <code>B</code> 语言，我们把它叫做 <strong>目标代码</strong>。整个的把源代码变为目标代码的过程，叫做 <strong>编译 <code>compiler</code></strong>。</p><p>一个完整的编译过程，非常复杂，下图大致的描述了完整的编译步骤。</p><p><img src="https://qn.huat.xyz/mac/202408211627375.jpg" alt="634fc00b09ac08e714721372"></p><p>由图可知，一个完善的编译流程非常复杂。</p><p>但是对于 <code>vue</code> 的 <code>compiler</code> 而言，因为他只是一个领域特定语言（DSL）编译器，所以它的一个编译流程会简化很多，如下图所示：</p><p><img src="https://qn.huat.xyz/mac/202408211628326.jpg" alt="634fc0160942893b13060948"></p><p>由上图可知，整个的一个编译流程，被简化为了 <code>4</code> 步。</p><p>其中的错误分析就包含了词法分析、语法分析。这个我们不需要过于关注。</p><p>我们的关注点只需要放到 <code>parse</code>、<code>transform</code>、<code>generate</code> 中即可。</p>',12),p=[r];function a(s,_,n,i,l,m){return c(),o("div",null,p)}const f=e(d,[["render",a]]);export{h as __pageData,f as default};
